import{_ as e,a as t}from"./chunks/station-form.bf54c130.js";import{_ as n,o as i,c as o,Q as s}from"./chunks/framework.b67c47e6.js";const a="/assets/production-lines-view.d48fcf49.svg",r="/assets/machine-settings.5644e630.svg",h="/assets/action-trigger.dd67e8e6.svg",v=JSON.parse('{"title":"Production Lines","description":"","frontmatter":{},"headers":[],"relativePath":"guide/management/production_lines/index.md","filePath":"guide/management/production_lines/index.md","lastUpdated":1790701315000}'),l={name:"guide/management/production_lines/index.md"},d=s('<h1 id="production-lines" tabindex="-1">Production Lines <a class="header-anchor" href="#production-lines" aria-label="Permalink to &quot;Production Lines&quot;">​</a></h1><p>A company must have at least one production line defined in the system.</p><p><strong>Production Settings</strong> is a group in the <strong>Settings</strong> section of the left menu, in company-wide mode, with three views. <strong>Production lines</strong> holds the lines and their stations. <strong>Machine Settings</strong> holds the machine setups. <strong>Automations</strong> holds the webhooks, the action triggers and the setups they run: machine files and drawings.</p><p>File generation templates are not here — they live in <strong>File settings</strong>, under the Files section of the menu. See <a href="/guide/reports/">Reports</a>.</p><h2 id="the-production-lines-view" tabindex="-1">The Production lines view <a class="header-anchor" href="#the-production-lines-view" aria-label="Permalink to &quot;The Production lines view&quot;">​</a></h2><p>The view starts with a <strong>New Production Line</strong> tile. Below it, each production line is a row: a header with its name, what it builds, its machine, its client IDs, its counts (stations, checklist items, machines, worktime capacity) and its actions (edit, copy, delete), and below it the cards of its stations in the order the line runs them.</p><p>Rows can be collapsed with the arrow on the left. They all start open, and the ones you collapse stay collapsed the next time you open the view.</p><p>Lines are grouped by what they build: modules first, then assemblies, then parts. A line that builds more than one of these appears once, under the largest one. Lines with an unrecognised tipo go to a last group, <em>Other</em>.</p><p><img src="'+a+'" alt="A production line row"></p><ol><li>The name of the line and what it builds.</li><li>The machine of the line. In grey italics when it is read from the line&#39;s only machine station.</li><li>The counts: stations, checklist items, machines and worktime capacity.</li><li>The drag handle and the position of the station in the line.</li><li>A station that is in several lines.</li><li>The two tiles to add a station. See <a href="#working-with-stations">Working with stations</a>.</li></ol><h3 id="the-production-line-form" tabindex="-1">The production line form <a class="header-anchor" href="#the-production-line-form" aria-label="Permalink to &quot;The production line form&quot;">​</a></h3><p>The production line (PL) itself has the following fields:</p><ul><li><strong>Name</strong>: A name to identify the PL.</li><li><strong>Client ID</strong>: An optional list of external identifiers used to link the production line to external systems (e.g. ERP or planning software). Multiple IDs can be added when the line needs to be matched from more than one external source.</li><li><strong>Tipo</strong>: The assembly, module or part categories that the PL can produce. At least one is required.</li><li><strong>Line machine</strong>: see <a href="#the-machine-of-a-line">The machine of a line</a>.</li><li><strong>Worktime Capacity</strong>: the capacity of the line, in minutes.</li><li><strong>Stations</strong>: on the right side of the form, the stations of the line in order. <strong>Add station</strong> adds an existing station, you drag a station to change the order, and its menu removes it from the line.</li></ul><p><img src="'+e+'" alt="The production line form"></p><ol><li>What the line builds. At least one is required.</li><li>The line machine. See <a href="#the-machine-of-a-line">The machine of a line</a>.</li><li>The stations of the line, in order. Drag to reorder; the menu removes a station from the line.</li></ol><p>Production lines (PLs) are expected to have at least 1 station. Stations represent steps in the production process.</p><h3 id="working-with-stations" tabindex="-1">Working with stations <a class="header-anchor" href="#working-with-stations" aria-label="Permalink to &quot;Working with stations&quot;">​</a></h3><p>At the end of every line there are two tiles:</p><ul><li><strong>New Production station</strong> creates a station and adds it to that line.</li><li><strong>Add existing station</strong> lists every station that is not already in the line, including the ones with no line at all.</li></ul><p>A station card shows its position in the line, its name, its client station ID, its number of checklist items, its expected worktime, its machine (or <em>Manual</em> when it has none), when it is enabled, and its zones, branches, assembly prefixes and drawing numbers when it has any.</p><p><strong>Reordering</strong> is done by dragging a station card by its handle. The new order is saved as soon as you drop the card. You cannot drag a card from one line into another: to move a station, add it to the new line and then remove it from the old one.</p><p>A station can belong to <strong>several lines</strong> at once. It then gets a card in each of them, marked <strong>Shared</strong>, and its cards list the lines it is in. It is the same station in all of them, so editing it from any line changes it everywhere. Its position, on the other hand, belongs to each line separately.</p><p>Stations that belong to <strong>no line</strong> are listed at the end of the view, under <em>No production line</em>. This is normal — a station can be created or left without a line — and it is the only place where you can reach them.</p><p>If two stations in the same production line share a zone, a warning is shown at the top of the line, naming the duplicated zone and the stations it is in.</p><p><strong>Deleting a station</strong> asks what you mean:</p><ul><li><em>Remove from this line</em> takes it out of that line only. The station stays, and if it was in no other line it moves to the <em>No production line</em> group.</li><li><em>Delete</em> removes the station from every line and loses its checklist. This cannot be undone.</li></ul><h3 id="the-station-form" tabindex="-1">The station form <a class="header-anchor" href="#the-station-form" aria-label="Permalink to &quot;The station form&quot;">​</a></h3><p>Station fields:</p><ul><li><strong>Name</strong>: Simply a name.</li><li><strong>Client ID</strong>: Client ID of the station, usually from an external application that the client wants to link.</li><li><strong>Machine station</strong>: tick it if the station runs on a machine, then pick its <strong>Machine setup</strong>. For example: a Mobi One setup created in <strong>Machine Settings</strong>. Without it, the station is a manual station. Give each machine station its own machine setup: two stations sharing one setup lose the zones of the first.</li><li><strong>Enable when</strong>: when the station is part of a panel&#39;s checklist: <em>Always</em>, <em>If Branch in Design</em>, <em>If Zone in Design</em> or <em>If Branch in Zone of Design</em>, using the <strong>Branches</strong> and <strong>Zones</strong> below.</li><li><strong>Branches</strong>: the branches the station looks for.</li><li><strong>Zones (Assemblies)</strong>: What zones are expected to be produced in this station. For example add 0 for a typical framing station. On a machine station, these are the zones it writes into the machine files: a zone that no station lists is not in the files, and a zone listed twice is written by the first station of the line. See <a href="/guide/machine_files/formats/panel_mob2/#how-a-file-is-made">How a file is made</a>.</li><li><strong>Assembly Prefixes (Modules)</strong>: the assembly prefixes the station works with, for module lines.</li><li><strong>DWG Numbers Filter</strong> and <strong>Default DWG</strong>: which drawings, by drawing number, the viewer shows at this station, and the one it opens first. Leave the filter empty to show them all.</li><li><strong>Expected productivity</strong>: the expected pace of the station, typed either as m²/min or as min/m²; the other value is filled in for you.</li></ul><p><img src="'+t+'" alt="The station form, with one checklist task"></p><ol><li>The machine setup of a machine station.</li><li>When the task is included.</li><li>How often the task is included. Here: one checklist in every five.</li><li>What the worker has to add to complete the task.</li><li>When the station itself is part of a panel&#39;s checklist.</li></ol><h3 id="checklist-tasks" tabindex="-1">Checklist tasks <a class="header-anchor" href="#checklist-tasks" aria-label="Permalink to &quot;Checklist tasks&quot;">​</a></h3><p>As a last nested item, each station has a <strong>Checklist</strong>: the entries for the production users to check in the production interface (&quot;the viewer&quot;). <strong>Add item</strong> adds a task, and each task has an <strong>Options</strong> menu to move it up or down or delete it.</p><p>Checklist fields:</p><ul><li><strong>Task text</strong>: The text that will be shown to the production user.</li><li><strong>Branches</strong> and <strong>Zones</strong>: used by <em>Enable when</em>.</li><li><strong>Enable when</strong>: when the task is included: <em>Always</em>, <em>If Branch in Design</em> (one of its branches is in the design), <em>If Zone in Design</em> (one of its zones is in the design) or <em>If Branch in Zone of Design</em> (one of its branches is in one of its zones). The station&#39;s own <em>Enable when</em> is checked first: a task of a station that is not enabled is never included.</li><li><strong>QC Inclusion Criteria</strong>: <em>All proofs</em> means every checklist gets this task. <em>1/n</em> adds it to 1 checklist every n checklists; <em>1/n randomized</em> does the same at a random pace. The count is kept per batch, and the first panel of a batch always gets the task.</li><li><strong>DOCS</strong>: A feature that allows the company to add documentation specific to the task, such as guidelines, specifications, ... Save the station first to upload them.</li><li><strong>Require form</strong>: the task asks for a form, which you design with the button next to it. <strong>Expand this form as tasks in checklist</strong> shows each field of the form as a task of its own.</li><li><strong>QR field</strong>: the task asks for a QR scan.</li><li><strong>Require picture</strong>: the task asks for a picture.</li></ul><h3 id="the-machine-of-a-line" tabindex="-1">The machine of a line <a class="header-anchor" href="#the-machine-of-a-line" aria-label="Permalink to &quot;The machine of a line&quot;">​</a></h3><p>A line can name the machine it runs on. Tick <strong>Line machine</strong> in the line form and pick one.</p><p>There are two ways to record it, and both are fine:</p><ul><li><strong>On the line.</strong> Use this when the line <em>is</em> one machine — a saw line, a plates cutter. There are no stations to hang it on.</li><li><strong>On a single station.</strong> Use this when the line has one station and the machine belongs to it. Nothing changes for the lines you already set up this way.</li></ul><p>Either way, the machine&#39;s name appears on the line header, next to what the line builds. When it was read off a station rather than set on the line, it is shown in grey italics, so you can tell at a glance where it came from.</p><p>If a line has a machine <strong>and</strong> one of its stations has another one, the form says so. The line&#39;s machine is the one that counts for the line. It is a notice, not an error: the form saves either way.</p><p>A line with several stations that each have their own machine — an automated panel line — has no single machine to name. Give it one by creating an <strong>H&amp;M Mobi One V2 Production Line</strong> machine setup and picking it as the line machine. That setup exists to hold what belongs to the whole line rather than to one of its tables; it has no settings yet, and each one will appear as it starts being used. Pick it as the line machine only: a station must never use it, or the MOB v2 files of that line cannot be generated.</p><h3 id="picking-a-machine-setup" tabindex="-1">Picking a machine setup <a class="header-anchor" href="#picking-a-machine-setup" aria-label="Permalink to &quot;Picking a machine setup&quot;">​</a></h3><p>Both machine pickers — the one on a station and the one on a line — put the setups that usually go there first (under <strong>Machine stations</strong> or <strong>Line machines</strong>), and everything else under <strong>Other machines</strong>. Nothing is hidden: if you pick a setup from the second group, the form tells you where it normally goes and lets you carry on.</p><h2 id="machine-settings" tabindex="-1">Machine Settings <a class="header-anchor" href="#machine-settings" aria-label="Permalink to &quot;Machine Settings&quot;">​</a></h2><p><strong>Machine Settings</strong> starts with two tiles, <strong>New Machine setup</strong> and <strong>Import from JSON</strong>. Below them, the setups are grouped: first one group per production line, with the setups that line runs; then <em>Not in any production line</em>, for station and line machines that nothing uses yet; then the rest by machine type. Licensed types (wood profiles cutters, wood plates saw cutters, Voortman and Valk) show how many setups you have out of your licensed maximum.</p><p>Each card shows the model, the file types it <strong>Produces</strong>, and <strong>Used by</strong>: the stations and production lines that use the setup. It warns only when a station or line machine is used by nothing. Its buttons edit, copy, download as JSON, and delete the setup.</p><p>When you create a machine setup, the <strong>Model</strong> list is grouped by where that kind of machine goes:</p><ul><li><strong>Production line settings</strong> — holds what belongs to a whole line. Today that is <em>H&amp;M Mobi One V2 Production Line</em>.</li><li><strong>Machine stations</strong> — goes on a station of a line.</li><li><strong>Standalone machines</strong> — machines you send generated files to: saws, cutters, profilers. These can also be named as the machine of a logistics line.</li></ul><p>The setup window has a <strong>General</strong> tab (name, model, and what the model is: provider, where it attaches, and what it produces), and depending on the model a <strong>Machine file</strong> tab, a <strong>Machine setup</strong> tab with the machine settings, and one tab per file type it produces, holding the default job options for that file.</p><p>Most models have no settings of their own: a cutter is configured by the options of the file it is sent, not by a form here. When that is the case the General tab says so instead of showing you an empty form.</p><p><img src="'+r+'" alt="Machine Settings"></p><ol><li>One group per production line, with the setups that line runs.</li><li><strong>Used by</strong>: the stations and lines that use the setup.</li><li>A station setup that nothing uses.</li><li>A licensed type: setups in use out of your licensed maximum.</li></ol><h3 id="the-machine-configuration-file" tabindex="-1">The machine configuration file <a class="header-anchor" href="#the-machine-configuration-file" aria-label="Permalink to &quot;The machine configuration file&quot;">​</a></h3><p>Some machine models accept the machine&#39;s own configuration file (XML or INI), in the <strong>Machine file</strong> tab. Uploading it fills the <strong>Parsed params</strong>, shown next to the uploader as read-only JSON: the top level is open and each block can be expanded. The <strong>Current machine file</strong> card shows the file name and when it was parsed, so you always know how old the configuration is.</p><h2 id="automations" tabindex="-1">Automations <a class="header-anchor" href="#automations" aria-label="Permalink to &quot;Automations&quot;">​</a></h2><p>The Automations view holds the <strong>Webhooks</strong>, which send production events to external systems, and two things that work together: the <strong>setups</strong>, which say <em>how</em> something is generated, and the <strong>action triggers</strong>, which say <em>when</em>.</p><h3 id="machine-file-setups" tabindex="-1">Machine file setups <a class="header-anchor" href="#machine-file-setups" aria-label="Permalink to &quot;Machine file setups&quot;">​</a></h3><p>A machine file setup is a saved MOB v2 setup: how the machine file is built — operations, nailing, shifts and layers.</p><p>Running one takes a panel design and builds a MOB v2 file for <strong>every machine station of every production line</strong> of the company, one file per station. There is no way to limit it to a single line. There is no report in between: the files are stored with the design, in its <strong>Auto-generated machine files</strong> card, and a new run adds a new version of each file. Nothing is copied to the machines: take the files from there.</p><p>You use a machine file setup from two places:</p><ul><li>an <strong>action trigger</strong>, so it runs on its own when a design finishes its analysis, and</li><li><strong>Launch action</strong> on the designs table, to run it by hand on the designs you select.</li></ul><p>For files you check before they reach the machines, use the <strong>MOB v2 Machine File</strong> type in Production files instead. See <a href="/guide/machine_files/formats/panel_mob2/">MOB v2 Machine File</a>.</p><h3 id="drawing-setups" tabindex="-1">Drawing setups <a class="header-anchor" href="#drawing-setups" aria-label="Permalink to &quot;Drawing setups&quot;">​</a></h3><p>A drawing setup is a saved set of drawings. It decides:</p><ul><li><p><strong>Drawings to make</strong> — one drawing per zone of the panel, with the parts of the other zones drawn as a dashed outline. Pick any of:</p><ul><li><strong>Zone 0 (frame)</strong> — the woods-only layer, drawn as FRAME. When zone 0 also holds plates, they get a drawing of their own, <em>ZONE_0_PLATES</em>, with the frame as a dashed outline, so they do not hide the studs.</li><li><strong>Positive zones</strong> — drawn from the front.</li><li><strong>Negative zones</strong> — drawn from the back, because they are mounted after the panel is turned over.</li><li><strong>Custom branches</strong> — one drawing per custom part branch of the parsing setup that has parts in the panel (window frames, electrical boxes…), with the rest of the panel as a dashed outline. Drawn from the back only when all its parts are in negative zones.</li></ul><p>The first three are on by default. Front and back are the ones produuz.it finds when it reads the panel, the same as in the 3D viewer: each drawing shows the panel as the operator sees it.</p></li><li><p><strong>Scale of the drawings</strong> — <em>auto</em> by default: the largest standard scale (1:10, 1:20, 1:25, 1:50, 1:100) at which the panel and its dimensions fit the page. A fixed scale that does not fit falls back to auto.</p></li><li><p><strong>Parts list on each drawing</strong> — on by default.</p></li><li><p><strong>Draw the nail, screw and glue lines</strong> — on by default.</p></li><li><p><strong>Company banner in the title block</strong> — off by default. Turn it on to print your company banner on top of the title block of every drawing, and pick which one under <strong>Banner</strong>. The banners are the ones uploaded in your company resources, the same ones the QR stickers use.</p></li></ul><h4 id="what-a-drawing-shows" tabindex="-1">What a drawing shows <a class="header-anchor" href="#what-a-drawing-shows" aria-label="Permalink to &quot;What a drawing shows&quot;">​</a></h4><p>Each drawing is one A3 page with a frame and a title block: the panel, the zone, the drawing number, the project, which side it is seen from, the scale, the material of the zone, the revision and the date.</p><ul><li><strong>Dimensions</strong>, following the conventions of hand-made shop drawings. Heights are measured from the bottom. Lengths are measured from the bottom-left corner on a drawing seen from the front, and from the bottom-right corner on one seen from the back: that is the same corner of the panel, so a position reads the same on both sides. <ul><li><strong>Frame</strong>: along the bottom, first the position of every stud, measured to its left face and written from the corner; studs side by side (a king and a jack stud) count as one, by their left face. Under it, the openings: from the outer face of the frame to the inner face of the opening, then the clear size of the opening, the wall to the next one and so on, with the position from the corner under each value. Then the overall length. Up both sides, the sill height, the opening height and what is left above it, and the overall height on the right.</li><li><strong>Zones</strong>: both edges of every plate or batten, measured from the edge of the panel, so the joints between plates and any strip of frame a plate leaves uncovered are visible. Battens also get their position from the corner. The clear openings of the zone are added when the plate edges do not already give them. The overall is always the whole panel.</li><li>The partial sizes always add up to the overall.</li></ul></li><li><strong>Part references</strong> on every piece, the same ones as on the stickers and in the lists. When a piece is too small to hold its reference, the reference sits beside it with a line pointing into it. Pieces with the same reference that sit so close that their labels would crowd each other share one label, with a thin line to each piece.</li><li><strong>A parts list</strong>: reference, quantity, section and length for timbers; reference, quantity, width × length × thickness, material and cut-outs for plates; reference, quantity, size and material for the other parts of a custom branch.</li><li><strong>Openings</strong> with their size, <strong>nail, screw and glue lines</strong> with their spacing, <strong>holes</strong> with their size and their position from the corner, and the <strong>angle</strong> of every sloped edge.</li><li>The parts of the other zones as a dashed outline, and a small diagram of the zones marking the one on this drawing and the side it is seen from.</li></ul><p>On a panel&#39;s own drawings card, a drawing marked <strong>Needs review</strong> has something that could not be drawn or placed cleanly — a reference that found no free spot, for example. Open it and check it before using it.</p><p>Running one takes a design and writes the drawings straight into the design&#39;s files, marked as generated. There is no report in between.</p><p>You use a drawing setup from two places:</p><ul><li>an <strong>action trigger</strong>, so it runs on its own, and</li><li>the <strong>Launch action</strong> button on the designs and multipanel groups tables, to run it by hand. Here the setup is optional: without one you get one drawing per zone.</li></ul><p>The design&#39;s drawings card shows whether a run is working or failed, and warns when a newer IFC arrived after the drawings were made, marking the outdated ones. <strong>Generate the drawings again</strong> from the same button; <strong>Clean</strong> deletes the generated ones without touching the drawings you uploaded yourself.</p><p>Each setup table has a <strong>Used by</strong> column naming the action triggers that use the setup. Deleting a setup also deletes the triggers that use it; the delete dialog lists them first.</p><h3 id="action-triggers" tabindex="-1">Action triggers <a class="header-anchor" href="#action-triggers" aria-label="Permalink to &quot;Action triggers&quot;">​</a></h3><p>An action trigger runs something on its own when an event happens in production, with nobody clicking anything. Besides a name, it reads as three steps:</p><ol><li><strong>When this happens</strong> — the event. Today the only event is <em>A design finishes its analysis</em>.</li><li><strong>Only if</strong> — an optional condition on a field of the design (<code>name</code>, <code>tipo</code>, or a key of its client data), matched as a full word, a prefix, or &quot;contains&quot;. Leave it empty and the trigger applies to every design.</li><li><strong>Then do this</strong> — the action, and the setup it runs with: <ul><li><em>Generate MOB v2 files and send them to the machines</em>, with a machine file setup.</li><li><em>Generate the drawings of the design</em>, with a drawing setup — or none, for the default views.</li></ul></li></ol><p>In the table, a MOB trigger with no setup is marked <em>No setup picked</em>, and a drawings trigger with no setup is marked <em>Default views</em>.</p><p><img src="'+h+'" alt="The action trigger form"></p><ol><li><em>Only if</em>: here, only designs whose <code>tipo</code> starts with <code>W</code>.</li><li>The setup the action runs with.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A trigger runs for <strong>every</strong> design that matches, each time it finishes its analysis. Use <em>Only if</em> to narrow it down before turning one on in a busy project.</p></div>',82),c=[d];function g(p,m,u,f,w,y){return i(),o("div",null,c)}const T=n(l,[["render",g]]);export{v as __pageData,T as default};
